function pctFmt(){return '0.0%;\\(0.0%\\)';}
const drv = ss.getSheetByName('Meta Drivers');
const model = ss.getSheetByName('Meta Model');

// Log current evidence before edit
log({
  drivers_before: drv.getRange('G19:K21').getDisplayValues(),
  model_before: {
    revenue_formulas: model.getRange('F13:J13').getFormulas()[0],
    revenue_values: model.getRange('F12:J14').getDisplayValues()
  }
});

// Meta Drivers: base mix grows linearly from 2023 actual mix to 5.0% by 2028
const baseFormulas = [[
  "=('Meta Model'!$E$13/'Meta Model'!$E$14)+((G$14-$F$14)/($K$14-$F$14))*(0.05-('Meta Model'!$E$13/'Meta Model'!$E$14))",
  "=('Meta Model'!$E$13/'Meta Model'!$E$14)+((H$14-$F$14)/($K$14-$F$14))*(0.05-('Meta Model'!$E$13/'Meta Model'!$E$14))",
  "=('Meta Model'!$E$13/'Meta Model'!$E$14)+((I$14-$F$14)/($K$14-$F$14))*(0.05-('Meta Model'!$E$13/'Meta Model'!$E$14))",
  "=('Meta Model'!$E$13/'Meta Model'!$E$14)+((J$14-$F$14)/($K$14-$F$14))*(0.05-('Meta Model'!$E$13/'Meta Model'!$E$14))",
  "=('Meta Model'!$E$13/'Meta Model'!$E$14)+((K$14-$F$14)/($K$14-$F$14))*(0.05-('Meta Model'!$E$13/'Meta Model'!$E$14))"
]];
drv.getRange('G19:K19').setFormulas(baseFormulas);
drv.getRange('G20:K20').setFormulas([["=G19+$M$20","=H19+$M$20","=I19+$M$20","=J19+$M$20","=K19+$M$20"]]);
drv.getRange('G21:K21').setFormulas([["=G19-$M$21","=H19-$M$21","=I19-$M$21","=J19-$M$21","=K19-$M$21"]]);
drv.getRange('G19:K21').setNumberFormat(pctFmt());

// Hard-code bull/bear deltas and border
const deltaRange = drv.getRange('M20:M21');
deltaRange.setValues([[0.005],[0.005]]);
deltaRange.setNumberFormat(pctFmt());
deltaRange.setBorder(true,true,true,true,true,true,'#000000',SpreadsheetApp.BorderStyle.SOLID);

// Meta Model: Reality Labs revenue = FoA * mix / (1 - mix)
model.getRange('F13:J13').setFormulas([[ 
  "=F12*INDEX('Meta Drivers'!G$19:G$21,MATCH($D$5,'Meta Drivers'!$C$19:$C$21,0))/(1-INDEX('Meta Drivers'!G$19:G$21,MATCH($D$5,'Meta Drivers'!$C$19:$C$21,0)))",
  "=G12*INDEX('Meta Drivers'!H$19:H$21,MATCH($D$5,'Meta Drivers'!$C$19:$C$21,0))/(1-INDEX('Meta Drivers'!H$19:H$21,MATCH($D$5,'Meta Drivers'!$C$19:$C$21,0)))",
  "=H12*INDEX('Meta Drivers'!I$19:I$21,MATCH($D$5,'Meta Drivers'!$C$19:$C$21,0))/(1-INDEX('Meta Drivers'!I$19:I$21,MATCH($D$5,'Meta Drivers'!$C$19:$C$21,0)))",
  "=I12*INDEX('Meta Drivers'!J$19:J$21,MATCH($D$5,'Meta Drivers'!$C$19:$C$21,0))/(1-INDEX('Meta Drivers'!J$19:J$21,MATCH($D$5,'Meta Drivers'!$C$19:$C$21,0)))",
  "=J12*INDEX('Meta Drivers'!K$19:K$21,MATCH($D$5,'Meta Drivers'!$C$19:$C$21,0))/(1-INDEX('Meta Drivers'!K$19:K$21,MATCH($D$5,'Meta Drivers'!$C$19:$C$21,0)))"
]]);

SpreadsheetApp.flush();

log({
  drivers_after_formulas: drv.getRange('G19:K21').getFormulas(),
  drivers_after_values: drv.getRange('G19:M21').getDisplayValues(),
