    case: model.getRange('D5').getDisplayValue(),
    rl_formulas: model.getRange('F13:J13').getFormulas()[0],
    revenues: model.getRange('F12:J14').getDisplayValues(),
    total_growth: model.getRange('F15:J15').getDisplayValues()[0]
  }
});
